create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','admin','super_admin');
create type public.product_availability as enum ('available','unavailable','out_of_stock','archived');
create type public.order_state as enum ('pending','confirmed','preparing','out_for_delivery','delivered','cancelled');
create type public.payment_method as enum ('cash_on_delivery');
create type public.payment_state as enum ('pending','collected','not_collected','cancelled');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade,role public.app_role not null default 'customer',assigned_by uuid references auth.users(id),assigned_at timestamptz not null default now());
create table public.food_categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,active boolean not null default true,display_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.food_items(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.food_categories(id),name text not null,variant_name text not null default 'Standard',weight_grams int not null check(weight_grams>0),price_cents int not null check(price_cents>=0),pieces_per_pack int not null check(pieces_per_pack>0),currency char(3) not null default 'SGD' check(currency='SGD'),short_description text,star_marked boolean not null default false,ready_to_eat boolean not null default false,frozen_available boolean default null,availability public.product_availability not null default 'available',featured boolean not null default false,display_order int not null default 0,archived boolean not null default false,requires_business_validation boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint star_rule check(not star_marked or (ready_to_eat=true and frozen_available=false)),unique(name,variant_name,weight_grams));
create table public.product_images(id uuid primary key default gen_random_uuid(),food_item_id uuid not null references public.food_items(id) on delete cascade,storage_path text not null,alt_text text not null,is_primary boolean not null default false,display_order int not null default 0,created_at timestamptz not null default now());
create unique index one_primary_image_per_product on public.product_images(food_item_id) where is_primary;
create table public.delivery_addresses(id uuid primary key default gen_random_uuid(),customer_id uuid not null references auth.users(id) on delete cascade,label text not null,line1 text not null,line2 text,postal_code text not null,is_default boolean not null default false,created_at timestamptz not null default now());
create table public.application_settings(key text primary key,value jsonb not null,description text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique,customer_id uuid not null references auth.users(id),customer_name_snapshot text not null,customer_phone_snapshot text not null,delivery_address_snapshot jsonb not null,subtotal_cents int not null check(subtotal_cents>=0),delivery_charge_cents int not null check(delivery_charge_cents>=0),final_total_cents int generated always as (subtotal_cents+delivery_charge_cents) stored,currency char(3) not null default 'SGD' check(currency='SGD'),payment_method public.payment_method not null default 'cash_on_delivery',payment_status public.payment_state not null default 'pending',order_status public.order_state not null default 'pending',customer_instructions text,cancellation_reason text,cancelled_by uuid references auth.users(id),cancelled_at timestamptz,delivered_at timestamptz,latest_admin_id uuid references auth.users(id),idempotency_key uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(customer_id,idempotency_key));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,food_item_id uuid references public.food_items(id) on delete set null,product_name_snapshot text not null,variant_snapshot text not null,weight_grams_snapshot int not null,price_cents_snapshot int not null,pieces_per_pack_snapshot int not null,quantity int not null check(quantity>0),line_total_cents int not null check(line_total_cents>=0),created_at timestamptz not null default now());
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,previous_status public.order_state,new_status public.order_state not null,updated_by uuid not null references auth.users(id),note text,created_at timestamptz not null default now());
create table public.admin_activity_logs(id uuid primary key default gen_random_uuid(),actor_id uuid not null references auth.users(id),action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index orders_customer_idx on public.orders(customer_id,created_at desc);create index orders_status_idx on public.orders(order_status,created_at desc);create index food_category_idx on public.food_items(category_id,display_order);create index food_availability_idx on public.food_items(availability,archived);create index food_search_idx on public.food_items using gin(to_tsvector('simple',name||' '||variant_name));create index history_order_idx on public.order_status_history(order_id,created_at);create index activity_date_idx on public.admin_activity_logs(created_at desc);

create or replace function public.has_role(required public.app_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role=required)$$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role in ('admin','super_admin'))$$;
create or replace function public.new_user_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));insert into user_roles(user_id,role) values(new.id,'customer');return new;end$$;
create trigger auth_user_created after insert on auth.users for each row execute function public.new_user_profile();

alter table profiles enable row level security;alter table user_roles enable row level security;alter table food_categories enable row level security;alter table food_items enable row level security;alter table product_images enable row level security;alter table delivery_addresses enable row level security;alter table application_settings enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table order_status_history enable row level security;alter table admin_activity_logs enable row level security;
create policy profile_self_read on profiles for select using(id=auth.uid() or is_staff());create policy profile_self_update on profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy own_role_read on user_roles for select using(user_id=auth.uid() or has_role('super_admin'));create policy categories_public_read on food_categories for select using(active or is_staff());create policy categories_super_manage on food_categories for all using(has_role('super_admin')) with check(has_role('super_admin'));
create policy catalogue_public_read on food_items for select using((not archived and availability='available') or is_staff());create policy products_super_manage on food_items for all using(has_role('super_admin')) with check(has_role('super_admin'));create policy products_admin_availability on food_items for update using(is_staff()) with check(is_staff());
create policy images_public_read on product_images for select using(true);create policy images_super_manage on product_images for all using(has_role('super_admin')) with check(has_role('super_admin'));
create policy address_own_all on delivery_addresses for all using(customer_id=auth.uid()) with check(customer_id=auth.uid());create policy settings_public_read on application_settings for select using(true);create policy settings_super_manage on application_settings for all using(has_role('super_admin')) with check(has_role('super_admin'));
create policy orders_own_or_staff_read on orders for select using(customer_id=auth.uid() or is_staff());create policy order_items_own_or_staff_read on order_items for select using(exists(select 1 from orders o where o.id=order_id and (o.customer_id=auth.uid() or is_staff())));create policy history_own_or_staff_read on order_status_history for select using(exists(select 1 from orders o where o.id=order_id and (o.customer_id=auth.uid() or is_staff())));create policy activity_super_read on admin_activity_logs for select using(has_role('super_admin'));

insert into application_settings(key,value,description) values('minimum_delivery_amount_cents','5000','Minimum subtotal required for delivery'),('delivery_charge_cents','0','Delivery charge in cents'),('currency','"SGD"','Store currency'),('payment_method','"cash_on_delivery"','Only supported payment method') on conflict do nothing;

create or replace function public.place_order(p_address_id uuid,p_phone text,p_instructions text,p_items jsonb,p_idempotency_key uuid) returns uuid language plpgsql security definer set search_path=public as $$declare v_order uuid:=gen_random_uuid();v_subtotal int:=0;v_min int;v_fee int;v_addr jsonb;v_name text;v_item jsonb;v_food food_items%rowtype;begin if auth.uid() is null then raise exception 'authentication required';end if;select to_jsonb(a) into v_addr from delivery_addresses a where a.id=p_address_id and a.customer_id=auth.uid();if v_addr is null then raise exception 'invalid delivery address';end if;select full_name into v_name from profiles where id=auth.uid();select (value#>>'{}')::int into v_min from application_settings where key='minimum_delivery_amount_cents';select (value#>>'{}')::int into v_fee from application_settings where key='delivery_charge_cents';for v_item in select * from jsonb_array_elements(p_items) loop select * into v_food from food_items where id=(v_item->>'product_id')::uuid and availability='available' and not archived for share;if not found then raise exception 'product unavailable';end if;v_subtotal:=v_subtotal+(v_food.price_cents*v_food.pieces_per_pack*(v_item->>'quantity')::int);end loop;if v_subtotal<v_min then raise exception 'minimum order not reached';end if;insert into orders(id,order_number,customer_id,customer_name_snapshot,customer_phone_snapshot,delivery_address_snapshot,subtotal_cents,delivery_charge_cents,customer_instructions,idempotency_key) values(v_order,'RKJ-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(v_order::text,'-',''),1,6)),auth.uid(),v_name,p_phone,v_addr,v_subtotal,v_fee,p_instructions,p_idempotency_key);for v_item in select * from jsonb_array_elements(p_items) loop select * into v_food from food_items where id=(v_item->>'product_id')::uuid;insert into order_items(order_id,food_item_id,product_name_snapshot,variant_snapshot,weight_grams_snapshot,price_cents_snapshot,pieces_per_pack_snapshot,quantity,line_total_cents) values(v_order,v_food.id,v_food.name,v_food.variant_name,v_food.weight_grams,v_food.price_cents,v_food.pieces_per_pack,(v_item->>'quantity')::int,v_food.price_cents*v_food.pieces_per_pack*(v_item->>'quantity')::int);end loop;insert into order_status_history(order_id,new_status,updated_by,note) values(v_order,'pending',auth.uid(),'Customer placed order');return v_order;end$$;
grant execute on function public.place_order(uuid,text,text,jsonb,uuid) to authenticated;

create or replace function public.transition_order_status(p_order_id uuid,p_new_status order_state,p_note text default null) returns void language plpgsql security definer set search_path=public as $$declare old order_state;valid boolean:=false;begin if not is_staff() then raise exception 'forbidden';end if;select order_status into old from orders where id=p_order_id for update;valid:=(old='pending' and p_new_status in ('confirmed','cancelled')) or (old='confirmed' and p_new_status in ('preparing','cancelled')) or (old='preparing' and p_new_status in ('out_for_delivery','cancelled')) or (old='out_for_delivery' and p_new_status in ('delivered','cancelled'));if not valid then raise exception 'invalid status transition';end if;update orders set order_status=p_new_status,latest_admin_id=auth.uid(),updated_at=now(),delivered_at=case when p_new_status='delivered' then now() else delivered_at end,cancellation_reason=case when p_new_status='cancelled' then p_note else cancellation_reason end,cancelled_by=case when p_new_status='cancelled' then auth.uid() else cancelled_by end,cancelled_at=case when p_new_status='cancelled' then now() else cancelled_at end where id=p_order_id;insert into order_status_history(order_id,previous_status,new_status,updated_by,note) values(p_order_id,old,p_new_status,auth.uid(),p_note);insert into admin_activity_logs(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'order_status_changed','order',p_order_id,jsonb_build_object('from',old,'to',p_new_status));end$$;
grant execute on function public.transition_order_status(uuid,order_state,text) to authenticated;
